import React, { useState, useEffect, useMemo } from "react";

const GST_OPTIONS = [0, 5, 12, 18, 28];
const STORAGE_KEY = "medicines";
const SALES_KEY = "sales";
const PATIENTS_KEY = "patients";
const PRESCRIPTIONS_KEY = "prescriptions";
const ROLE_KEY = "active-role";
const PATIENT_RETENTION_DAYS = 30;
const ROLES = {
  admin: {
    label: "Admin",
    description: "Full access",
    tabs: [
      "dashboard",
      "billing",
      "inventory",
      "patients",
      "prescriptions",
      "invoices",
    ],
    canManageInventory: true,
  },
  doctor: {
    label: "Doctor",
    description: "OPD and patient records",
    tabs: ["patients", "prescriptions", "medicines"],
    canManageInventory: false,
  },
  reception: {
    label: "Reception desk",
    description: "Register OPD patients",
    tabs: ["patients"],
    canManageInventory: false,
  },
  staff: {
    label: "Store staff",
    description: "Billing and stock",
    tabs: ["billing", "inventory", "prescriptions", "invoices"],
    canManageInventory: false,
  },
  pathology: {
    label: "Pathology",
    description: "Review prescribed tests",
    tabs: ["pathology", "billing", "invoices"],
    canManageInventory: false,
  },
};
const DOCTORS = [
  { id: "dr-raj", name: "Dr. Raunak Raj" },
  { id: "dr-singh", name: "Dr. S K Singh" },
  { id: "dr-kumari", name: "Dr. P kumari" },
  { id: "dr-kumar", name: "Dr. Ashit Kumar" },
  { id: "dr-shrivastava", name: "Dr. D K Shrivastav" },
];
const DEPARTMENTS = [
  "General Physician",
  "Orthopaedic",
  "Gynae & Obs",
  "Pediatric",
  "Dermatology",
  "ENT",
  "General Surgery",
];
const COMPLAINT_OPTIONS = [
  "Abdominal pain",
  "Fever",
  "Cough and cold",
  "Headache",
  "Body pain",
  "Vomiting",
  "Loose motions",
  "Breathing difficulty",
  "Skin rash",
  "Joint pain",
  "Back pain",
  "Routine check-up",
  "Follow-up visit",
  "Other",
];

const HOSPITAL_LOGO = "/hospital-logo.svg";

function parseCsvLine(line) {
  const values = [];
  let value = "";
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const character = line[index];
    if (character === '"' && line[index + 1] === '"' && quoted) {
      value += '"';
      index += 1;
    } else if (character === '"') {
      quoted = !quoted;
    } else if (character === "," && !quoted) {
      values.push(value.trim());
      value = "";
    } else {
      value += character;
    }
  }
  values.push(value.trim());
  return values;
}

function parseProductCatalog(csv) {
  const lines = csv.split(/\r?\n/).filter(Boolean);
  const headers = parseCsvLine(lines.shift() || "");
  return lines
    .map((line) => {
      const values = parseCsvLine(line);
      const product = headers.reduce(
        (record, header, index) => ({
          ...record,
          [header]: values[index] || "",
        }),
        {},
      );
      return {
        id: `csv-${product["Drug Code"] || uid()}`,
        drugCode: product["Drug Code"],
        name: product["Generic Name"],
        unitSize: product["Unit Size"],
        batch: product["Drug Code"]
          ? `DRUG-${product["Drug Code"]}`
          : "CATALOG",
        expiry: "2099-12-31",
        qty: 999,
        price: Number(product.MRP) || 0,
        gst: 0,
        group: product["Group Name"],
      };
    })
    .filter((product) => product.name);
}

function parsePathologyCatalog(csv) {
  const lines = csv.split(/\r?\n/).filter(Boolean);
  const headers = parseCsvLine(lines.shift() || "");
  return lines
    .map((line) => {
      const values = parseCsvLine(line);
      const test = headers.reduce(
        (record, header, index) => ({
          ...record,
          [header]: values[index] || "",
        }),
        {},
      );
      return {
        id: `lab-${uid()}`,
        name: test["Test / Investigation"] || test["Test Name"],
        category: test.Category,
        price: Number(String(test.Price || "").replace(/[^0-9.]/g, "")) || 0,
      };
    })
    .filter((test) => test.name);
}

async function readStoredValue(key) {
  if (window.storage?.get) return window.storage.get(key, false);
  return { value: window.localStorage.getItem(key) };
}

async function writeStoredValue(key, value) {
  if (window.storage?.set) return window.storage.set(key, value, false);
  window.localStorage.setItem(key, value);
  return null;
}

function mergeCatalogWithStored(storedMedicines, catalog) {
  const catalogByKey = new Map(
    catalog.map((medicine) => [
      medicine.drugCode || medicine.name.toLowerCase(),
      medicine,
    ]),
  );
  const storedKeys = new Set();
  const updated = storedMedicines.map((medicine) => {
    const key = medicine.drugCode || medicine.name.toLowerCase();
    const catalogMedicine = catalogByKey.get(key);
    if (!catalogMedicine) return medicine;
    storedKeys.add(key);
    return {
      ...catalogMedicine,
      id: medicine.id,
      qty: medicine.qty,
      batch: medicine.batch,
      expiry: medicine.expiry,
      gst: medicine.gst,
    };
  });
  return [
    ...updated,
    ...catalog.filter(
      (medicine) =>
        !storedKeys.has(medicine.drugCode || medicine.name.toLowerCase()),
    ),
  ];
}

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function createPatientId() {
  return `SRN-${Date.now().toString().slice(-8)}-${uid().toUpperCase()}`;
}

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const target = new Date(dateStr);
  return Math.round((target - today) / (1000 * 60 * 60 * 24));
}

function expiryStatus(dateStr) {
  const d = daysUntil(dateStr);
  if (d === null) return { label: "—", tone: "neutral" };
  if (d < 0) return { label: "Expired", tone: "danger" };
  if (d <= 30) return { label: `${d}d left`, tone: "danger" };
  if (d <= 90) return { label: `${d}d left`, tone: "warn" };
  return { label: `${d}d left`, tone: "ok" };
}

function currency(n) {
  return (
    "₹" +
    Number(n || 0).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })
  );
}

function invoiceBreakdown(invoice) {
  const lines = invoice.lines || [];
  const labTests = invoice.labTests || [];
  const medicineSubtotal =
    invoice.medicineSubtotal ??
    lines.reduce((total, line) => total + (Number(line.lineBase) || 0), 0);
  const medicineGstTotal =
    invoice.medicineGstTotal ??
    lines.reduce((total, line) => total + (Number(line.lineGst) || 0), 0);
  const labSubtotal =
    invoice.labSubtotal ??
    labTests.reduce(
      (total, test) =>
        total + (Number(test.lineBase ?? test.lineTotal) || 0),
      0,
    );
  const medicineBeforeDiscount = medicineSubtotal + medicineGstTotal;
  const billBeforeDiscount = medicineBeforeDiscount + labSubtotal;
  const discountAmount = Number(invoice.discountAmount) || 0;
  const medicineDiscountAmount =
    invoice.medicineDiscountAmount ??
    (billBeforeDiscount
      ? (discountAmount * medicineBeforeDiscount) / billBeforeDiscount
      : 0);
  const labDiscountAmount =
    invoice.labDiscountAmount ??
    (billBeforeDiscount
      ? (discountAmount * labSubtotal) / billBeforeDiscount
      : 0);
  return {
    medicineSubtotal,
    medicineGstTotal,
    medicineDiscountAmount,
    medicineGrandTotal: medicineBeforeDiscount - medicineDiscountAmount,
    labSubtotal,
    labDiscountAmount,
    labGrandTotal: labSubtotal - labDiscountAmount,
  };
}

function isOlderThanDays(dateString, days) {
  if (!dateString) return false;
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return false;
  return Date.now() - date.getTime() > days * 24 * 60 * 60 * 1000;
}

function isWithinLastDays(dateString, days) {
  if (!dateString) return false;
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return false;
  return date.getTime() <= Date.now() && !isOlderThanDays(dateString, days);
}

const SEED = [
  {
    id: uid(),
    name: "Paracetamol 500mg",
    batch: "PC22B",
    expiry: "2027-03-01",
    qty: 240,
    price: 1.5,
    gst: 12,
  },
  {
    id: uid(),
    name: "Amoxicillin 250mg",
    batch: "AX09L",
    expiry: "2026-10-05",
    qty: 60,
    price: 4.2,
    gst: 12,
  },
  {
    id: uid(),
    name: "Cetirizine 10mg",
    batch: "CT41A",
    expiry: "2026-11-20",
    qty: 150,
    price: 1.1,
    gst: 5,
  },
  {
    id: uid(),
    name: "ORS Sachet",
    batch: "OR03C",
    expiry: "2028-01-15",
    qty: 300,
    price: 8,
    gst: 0,
  },
];

const SEED_PATIENTS = [
  {
    id: uid(),
    name: "Aarav Mehta",
    phone: "9876543210",
    ageGender: "45Y / M",
    weight: "78 kg",
    problem: "Hypertension follow-up",
    doctorId: "dr-sharma",
    doctor: "Dr. Sharma",
    visitDate: new Date().toISOString().slice(0, 10),
    status: "Waiting for doctor",
  },
  {
    id: uid(),
    name: "Neha Sharma",
    phone: "9812345678",
    ageGender: "32Y / F",
    weight: "60 kg",
    problem: "Seasonal allergy",
    doctorId: "dr-patel",
    doctor: "Dr. Patel",
    visitDate: new Date().toISOString().slice(0, 10),
    status: "Waiting for doctor",
  },
];

export default function App() {
  const [medicines, setMedicines] = useState(null);
  const [tab, setTab] = useState("dashboard");
  const [search, setSearch] = useState("");
  const [cart, setCart] = useState([]); // {id, qty}
  const [discountPercent, setDiscountPercent] = useState(0);
  const [lastInvoice, setLastInvoice] = useState(null);
  const [sales, setSales] = useState([]);
  const [patients, setPatients] = useState(null);
  const [prescriptions, setPrescriptions] = useState([]);
  const [pathologyTests, setPathologyTests] = useState([]);
  const [billLabTests, setBillLabTests] = useState([]);
  const [patient, setPatient] = useState({
    name: "",
    doctor: "",
    ageGender: "",
    staff: "",
  });
  const [billingPatientId, setBillingPatientId] = useState("");
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [patientSearch, setPatientSearch] = useState("");
  const [medicineSearch, setMedicineSearch] = useState("");
  const [selectedPatientId, setSelectedPatientId] = useState(null);
  const [patientFormOpen, setPatientFormOpen] = useState(false);
  const [prescriptionFormOpen, setPrescriptionFormOpen] = useState(false);
  const [prescriptionPatientId, setPrescriptionPatientId] = useState("");
  const [prescriptionEditing, setPrescriptionEditing] = useState(null);
  const [printPrescription, setPrintPrescription] = useState(null);
  const [printBillType, setPrintBillType] = useState(null);
  const [activeDoctorId, setActiveDoctorId] = useState(DOCTORS[0].id);
  const [doctorView, setDoctorView] = useState("today");
  const [saveState, setSaveState] = useState("idle"); // idle | saving | saved
  const [role, setRole] = useState(() => {
    try {
      return window.localStorage.getItem(ROLE_KEY) || "admin";
    } catch (e) {
      return "admin";
    }
  });
  const activeRole = ROLES[role] || ROLES.admin;

  useEffect(() => {
    (async () => {
      let catalog = [];
      try {
        const catalogResponse = await fetch("/products.csv");
        if (catalogResponse.ok)
          catalog = parseProductCatalog(await catalogResponse.text());
      } catch (e) {}
      try {
        const res = await readStoredValue(STORAGE_KEY);
        if (res && res.value) {
          const storedMedicines = JSON.parse(res.value);
          setMedicines(mergeCatalogWithStored(storedMedicines, catalog));
        } else {
          setMedicines([...SEED, ...catalog]);
        }
      } catch (e) {
        setMedicines([...SEED, ...catalog]);
      }
    })();
  }, []);

  useEffect(() => {
    fetch("/pathology-tests.csv")
      .then((response) => (response.ok ? response.text() : ""))
      .then((text) =>
        setPathologyTests(text ? parsePathologyCatalog(text) : []),
      )
      .catch(() => setPathologyTests([]));
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const [patientResult, prescriptionResult] = await Promise.all([
          readStoredValue(PATIENTS_KEY),
          readStoredValue(PRESCRIPTIONS_KEY),
        ]);
        const storedPatients =
          patientResult && patientResult.value
            ? JSON.parse(patientResult.value)
            : SEED_PATIENTS;
        const retainedPatients = storedPatients.filter(
          (patient) =>
            !isOlderThanDays(
              patient.lastVisitDate || patient.visitDate || patient.createdAt,
              PATIENT_RETENTION_DAYS,
            ),
        );
        const retainedPatientIds = new Set(
          retainedPatients.map((patient) => patient.id),
        );
        setPatients(
          retainedPatients.map((patient, index) => ({
            ...patient,
            patientUid: patient.patientUid || createPatientId(),
            doctorId: patient.doctorId || DOCTORS[index % DOCTORS.length].id,
            doctor: patient.doctor || DOCTORS[index % DOCTORS.length].name,
            visitDate:
              patient.visitDate || new Date().toISOString().slice(0, 10),
          })),
        );
        if (prescriptionResult && prescriptionResult.value)
          setPrescriptions(
            JSON.parse(prescriptionResult.value).filter(
              (prescription) =>
                retainedPatientIds.has(prescription.patientId) &&
                !isOlderThanDays(
                  prescription.createdAt,
                  PATIENT_RETENTION_DAYS,
                ),
            ),
          );
      } catch (e) {
        setPatients(
          SEED_PATIENTS.map((patient, index) => ({
            ...patient,
            patientUid: patient.patientUid || createPatientId(),
            doctorId: patient.doctorId || DOCTORS[index % DOCTORS.length].id,
            doctor: patient.doctor || DOCTORS[index % DOCTORS.length].name,
          })),
        );
        setPrescriptions([]);
      }
    })();
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const res = await readStoredValue(SALES_KEY);
        if (res && res.value) setSales(JSON.parse(res.value));
      } catch (e) {
        setSales([]);
      }
    })();
  }, []);

  useEffect(() => {
    if (medicines === null) return;
    setSaveState("saving");
    const t = setTimeout(async () => {
      try {
        await writeStoredValue(STORAGE_KEY, JSON.stringify(medicines));
        setSaveState("saved");
      } catch (e) {
        setSaveState("idle");
      }
    }, 250);
    return () => clearTimeout(t);
  }, [medicines]);

  useEffect(() => {
    if (sales.length === 0) return;
    try {
      writeStoredValue(SALES_KEY, JSON.stringify(sales)).catch(() => {});
    } catch (e) {}
  }, [sales]);

  useEffect(() => {
    if (patients === null) return;
    try {
      writeStoredValue(PATIENTS_KEY, JSON.stringify(patients));
      writeStoredValue(PRESCRIPTIONS_KEY, JSON.stringify(prescriptions));
    } catch (e) {}
  }, [patients, prescriptions]);

  useEffect(() => {
    try {
      window.localStorage.setItem(ROLE_KEY, role);
    } catch (e) {}
    const selectedRole = ROLES[role] || ROLES.admin;
    if (!selectedRole.tabs.includes(tab)) setTab(selectedRole.tabs[0]);
  }, [role, tab]);

  const filtered = useMemo(() => {
    if (medicines === null) return [];
    const q = search.trim().toLowerCase();
    if (!q) return medicines;
    return medicines.filter(
      (m) =>
        m.name.toLowerCase().includes(q) || m.batch.toLowerCase().includes(q),
    );
  }, [medicines, search]);

  function addToCart(med) {
    if (daysUntil(med.expiry) < 0) return;
    setCart((c) => {
      const found = c.find((i) => i.id === med.id);
      if (found) {
        return c.map((i) =>
          i.id === med.id ? { ...i, qty: Math.min(i.qty + 1, med.qty) } : i,
        );
      }
      if (med.qty <= 0) return c;
      return [...c, { id: med.id, qty: 1 }];
    });
  }

  function setCartQty(id, qty) {
    const med = medicines.find((m) => m.id === id);
    const clamped = Math.max(1, Math.min(qty || 1, med ? med.qty : qty));
    setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: clamped } : i)));
  }

  function removeFromCart(id) {
    setCart((c) => c.filter((i) => i.id !== id));
  }

  const cartLines =
    medicines === null
      ? []
      : cart
          .map((item) => {
            const med = medicines.find((m) => m.id === item.id);
            if (!med) return null;
            const lineBase = med.price * item.qty;
            const lineGst = (lineBase * med.gst) / 100;
            return {
              ...item,
              med,
              lineBase,
              lineGst,
              lineTotal: lineBase + lineGst,
            };
          })
          .filter(Boolean);
  const billLabTestLines = billLabTests.map((test) => ({
    ...test,
    lineBase: Number(test.price) || 0,
    lineGst: 0,
    lineTotal: Number(test.price) || 0,
  }));

  const subtotal =
    cartLines.reduce((s, l) => s + l.lineBase, 0) +
    billLabTestLines.reduce((s, l) => s + l.lineBase, 0);
  const gstTotal = cartLines.reduce((s, l) => s + l.lineGst, 0);
  const billBeforeDiscount = subtotal + gstTotal;
  const discountAmount = Math.min(
    billBeforeDiscount,
    (billBeforeDiscount * Number(discountPercent || 0)) / 100,
  );
  const grandTotal = billBeforeDiscount - discountAmount;
  const lowStockCount =
    medicines?.filter((m) => m.qty > 0 && m.qty <= 30).length || 0;
  const expiringCount =
    medicines?.filter((m) => {
      const days = daysUntil(m.expiry);
      return days !== null && days >= 0 && days <= 90;
    }).length || 0;
  const inventoryValue =
    medicines?.reduce(
      (total, medicine) => total + medicine.qty * medicine.price,
      0,
    ) || 0;
  const salesTotal = sales.reduce((total, sale) => total + sale.grandTotal, 0);
  const salesToday = sales.filter(
    (sale) => new Date(sale.date).toDateString() === new Date().toDateString(),
  );

  function completeSale() {
    if (cartLines.length === 0 && billLabTestLines.length === 0) return;
    setMedicines((meds) =>
      meds.map((m) => {
        const line = cartLines.find((l) => l.id === m.id);
        return line ? { ...m, qty: m.qty - line.qty } : m;
      }),
    );
    const medicineSubtotal = cartLines.reduce(
      (total, line) => total + line.lineBase,
      0,
    );
    const medicineGstTotal = cartLines.reduce(
      (total, line) => total + line.lineGst,
      0,
    );
    const labSubtotal = billLabTestLines.reduce(
      (total, line) => total + line.lineBase,
      0,
    );
    const breakdown = invoiceBreakdown({
      lines: cartLines,
      labTests: billLabTestLines,
      discountAmount,
      medicineSubtotal,
      medicineGstTotal,
      labSubtotal,
    });
    const invoice = {
      id: "INV-" + Date.now().toString().slice(-6),
      date: new Date(),
      patientId: billingPatientId || null,
      patient: { ...patient },
      lines: cartLines,
      labTests: billLabTestLines,
      ...breakdown,
      subtotal,
      gstTotal,
      discountPercent,
      discountAmount,
      grandTotal,
    };
    setLastInvoice(invoice);
    setSales((previous) => [invoice, ...previous].slice(0, 100));
    setCart([]);
    setBillLabTests([]);
    setDiscountPercent(0);
    setBillingPatientId("");
    setPatient({ name: "", doctor: "", ageGender: "", staff: "" });
  }

  function saveMedicine(data) {
    if (editing) {
      setMedicines((meds) =>
        meds.map((m) => (m.id === editing.id ? { ...m, ...data } : m)),
      );
    } else {
      setMedicines((meds) => [...meds, { id: uid(), ...data }]);
    }
    setFormOpen(false);
    setEditing(null);
  }

  async function importCatalog(event) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    const imported = parseProductCatalog(await file.text());
    if (imported.length === 0) return;
    setMedicines((current) => {
      const importedByKey = new Map(
        imported.map((medicine) => [
          medicine.drugCode || medicine.name.toLowerCase(),
          medicine,
        ]),
      );
      const existingKeys = new Set();
      const updated = current.map((medicine) => {
        const key = medicine.drugCode || medicine.name.toLowerCase();
        const catalogMedicine = importedByKey.get(key);
        if (!catalogMedicine) return medicine;
        existingKeys.add(key);
        return {
          ...catalogMedicine,
          id: medicine.id,
          qty: medicine.qty,
          batch: medicine.batch,
          expiry: medicine.expiry,
          gst: medicine.gst,
        };
      });
      return [
        ...updated,
        ...imported.filter(
          (medicine) =>
            !existingKeys.has(medicine.drugCode || medicine.name.toLowerCase()),
        ),
      ];
    });
  }

  function deleteMedicine(id) {
    setMedicines((meds) => meds.filter((m) => m.id !== id));
