  function savePatient(data) {
    const visitDate = new Date().toISOString().slice(0, 10);
    setPatients((items) => {
      const existing = items.find(
        (item) =>
          item.phone.replace(/\D/g, "") === data.phone.replace(/\D/g, ""),
      );
      if (!existing)
        return [
          ...items,
          {
            id: uid(),
            patientUid: createPatientId(),
            status: "Waiting for doctor",
            visitDate,
            lastVisitDate: visitDate,
            createdAt: new Date().toISOString(),
            visits: [
              { date: visitDate, problem: data.problem, doctor: data.doctor },
            ],
            ...data,
          },
        ];
      const previousVisits = existing.visits || [
        {
          date: existing.visitDate,
          problem: existing.problem,
          doctor: existing.doctor,
        },
      ];
      return items.map((item) =>
        item.id === existing.id
          ? {
              ...item,
              ...data,
              status: "Waiting for doctor",
              visitDate,
              lastVisitDate: visitDate,
              visits: [
                ...previousVisits,
                { date: visitDate, problem: data.problem, doctor: data.doctor },
              ],
            }
          : item,
      );
    });
    setPatientFormOpen(false);
  }

  function deletePatient(patientId) {
    setPatients((items) => items.filter((item) => item.id !== patientId));
    setPrescriptions((items) =>
