    setSelectedPatientId(null);
  }

  function removeExpiredPatients() {
    const expiredIds = new Set(
      patients
        .filter((item) =>
          isOlderThanDays(
            item.lastVisitDate || item.visitDate || item.createdAt,
            PATIENT_RETENTION_DAYS,
          ),
        )
        .map((item) => item.id),
    );
    if (expiredIds.size === 0) return;
    setPatients((items) => items.filter((item) => !expiredIds.has(item.id)));
    setPrescriptions((items) =>
      items.filter((item) => !expiredIds.has(item.patientId)),
    );
    setSelectedPatientId(null);
  }

  function savePrescription(data) {
    const existingPrescription = data.id
      ? prescriptions.find((item) => item.id === data.id)
      : null;
    const nextStatus =
      existingPrescription &&
      ["Prescription ready", "Sent to store", "Re-sent to store"].includes(
        existingPrescription.status,
      )
        ? "Re-sent to store"
        : "Sent to store";

    setPrescriptions((items) =>
      data.id
        ? items.map((item) =>
            item.id === data.id
              ? { ...item, ...data, status: nextStatus, sentToStore: true }
              : item,
          )
        : [
            {
              id: uid(),
              createdAt: new Date(),
              status: nextStatus,
              sentToStore: true,
              ...data,
            },
            ...items,
          ],
    );
    setPatients((items) =>
      items.map((item) =>
        item.id === data.patientId
          ? { ...item, doctor: data.doctor, status: nextStatus }
          : item,
      ),
    );
    setPrescriptionFormOpen(false);
    setPrescriptionPatientId("");
    setPrescriptionEditing(null);
  }

