                    <strong>{patientRecord?.name || "Unknown patient"}</strong>
                    <small>
                      {patientRecord?.problem || "Problem not recorded"} ·{" "}
                      {patientRecord?.weight || "Weight not recorded"}
                    </small>
                    <small>
                      {prescription.medicines
                        ?.map((line) => `${line.name} (${line.qty})`)
                        .join(", ") || prescription.medicineName}
                    </small>
                    <small>Dr. {prescription.doctor}</small>
                  </div>
                  <span
                    className={
                      prescription.status === "Dispensed"
                        ? "status ok"
                        : "status warn"
                    }
                  >
                    {prescription.status}
                  </span>
                  {role === "doctor" && (
                    <>
                      <button
                        className="btn small"
                        onClick={() => editPrescription(prescription)}
                      >
                        {prescription.status === "Sent to store" ||
                        prescription.status === "Re-sent to store"
                          ? "Edit & re-send"
                          : "Edit prescription"}
                      </button>
                      <button
                        className="btn small"
                        onClick={() => printPrescriptionDocument(prescription)}
                      >
                        Print prescription
                      </button>
                    </>
                  )}
                  {prescription.status !== "Dispensed" && role !== "doctor" && (
                    <>
                      {role === "staff" && (
                        <button
                          className="btn small"
                          onClick={() => printStorePrescriptionCopy(prescription)}
                        >
                          Print store copy
                        </button>
                      )}
                      <button
                        className="btn small"
                        onClick={() =>
                          markPrescriptionDispensed(prescription.id)
                        }
                      >
                        Mark dispensed
                      </button>
                      {patientRecord &&
                        role !== "pathology" &&
                        prescription.medicines?.length > 0 && (
                        <button
                          className="btn small"
                          onClick={() => startPrescriptionBilling(prescription)}
                        >
                          Generate medicine bill
                        </button>
                      )}
                    </>
                  )}
                </div>
              );
            })}
            {prescriptions.length === 0 && (
              <div className="empty">
                No prescriptions yet. Doctors can add the first OPD
                prescription.
              </div>
            )}
          </div>
        </main>
      )}

      {tab === "pathology" && (
        <main className="records-layout">
          <div className="section-heading">
            <div>
              <span className="eyebrow">Laboratory workflow</span>
              <h1>Prescribed pathology tests</h1>
              <p>Doctor-ordered investigations awaiting lab processing.</p>
            </div>
          </div>
          <div className="pathology-queue panel">
            <table className="stock-table pathology-table">
              <thead>
                <tr>
                  <th>Patient</th>
                  <th>Address</th>
                  <th>Doctor</th>
                  <th>Tests</th>
                  <th>Instructions</th>
                  <th>Status</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {prescriptions
                  .filter((prescription) => prescription.labTests?.length > 0)
                  .map((prescription) => {
                    const patientRecord = patients.find(
                      (item) => item.id === prescription.patientId,
                    );
                    const tests = prescription.labTests || [];
                    const completed = tests.every(
                      (test) => test.status === "Completed",
                    );
                    return (
                      <tr key={prescription.id}>
                        <td>
                          <strong>{patientRecord?.name || "Unknown patient"}</strong>
                          <small>{patientRecord?.patientUid || ""}</small>
                        </td>
                        <td>{patientRecord?.address || "—"}</td>
                        <td>{prescription.doctor || "—"}</td>
                        <td>{tests.map((test) => test.name).join(", ")}</td>
                        <td>
                          {tests
                            .filter((test) => test.instructions)
                            .map((test) => `${test.name}: ${test.instructions}`)
                            .join(", ") || "—"}
                        </td>
                        <td>
                          <span className={completed ? "status ok" : "status warn"}>
                            {completed ? "Completed" : "Pending"}
                          </span>
                        </td>
                        <td>
                          <button
                            className="btn small"
                            onClick={() => startPrescriptionBilling(prescription)}
                          >
                            Generate test bill
                          </button>
                          {!completed && (
                            <button
                              className="btn small"
                              onClick={() =>
                                markPathologyTestsCompleted(prescription.id)
                              }
                            >
                              Mark completed
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                {prescriptions.every(
                  (prescription) => !prescription.labTests?.length,
                ) && (
                  <tr>
                    <td colSpan="7" className="empty">
                      No pathology tests have been prescribed.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </main>
      )}

      {tab === "invoices" && (
        <main className="invoices-layout">
          <div className="section-heading">
            <div>
              <span className="eyebrow">Sales history</span>
              <h1>Invoices</h1>
              <p>Review completed bills and print a copy when needed.</p>
            </div>
            <button className="btn primary" onClick={() => setTab("billing")}>
              Create new bill
            </button>
          </div>
          <div className="invoice-history panel">
            {sales.map((sale) => (
              <div className="history-row" key={sale.id}>
                <div>
                  <strong>{sale.id}</strong>
                  <span>{new Date(sale.date).toLocaleString("en-IN")}</span>
                </div>
                <div>
                  <span>{sale.patient.name || "Walk-in patient"}</span>
                  <small>
                    {sale.lines.length} medicine
                    {sale.lines.length === 1 ? "" : "s"}
                  </small>
                </div>
                <strong>{currency(sale.grandTotal)}</strong>
                {sale.lines?.length > 0 && (
                  <button
                    className="btn small"
                    onClick={() => printBillDocument(sale, "medicine")}
                  >
                    Medicine bill
                  </button>
                )}
                {role === "pathology" && sale.labTests?.length > 0 && (
                  <button
                    className="btn small"
                    onClick={() => printBillDocument(sale, "pathology")}
                  >
                    Test bill
                  </button>
                )}
              </div>
            ))}
            {sales.length === 0 && (
              <div className="empty">No invoices have been completed yet.</div>
            )}
          </div>
        </main>
      )}

      {formOpen && (
        <MedicineForm
          initial={editing}
          onCancel={() => {
            setFormOpen(false);
            setEditing(null);
          }}
          onSave={saveMedicine}
        />
      )}
      {patientFormOpen && (
        <PatientRegistrationForm
          doctors={DOCTORS}
          onCancel={() => setPatientFormOpen(false)}
          onSave={savePatient}
        />
      )}
      {prescriptionFormOpen && (
        <PrescriptionFormModern
          patients={patients}
          medicines={medicines}
          pathologyTests={pathologyTests}
          initialPatientId={prescriptionPatientId}
          initialPrescription={prescriptionEditing}
          onCancel={() => {
            setPrescriptionFormOpen(false);
            setPrescriptionEditing(null);
            setPrescriptionPatientId("");
          }}
          onSave={savePrescription}
        />
      )}
    </div>
  );
}

