function PrescriptionFormModern({
  patients,
  medicines,
  pathologyTests,
  initialPatientId,
  initialPrescription,
  onCancel,
  onSave,
}) {
  const [patientId, setPatientId] = useState(
    initialPrescription?.patientId ||
      initialPatientId ||
      patients.find((patient) => patient.status === "Waiting for doctor")?.id ||
      patients[0]?.id ||
      "",
  );
  const selectedPatient = patients.find((patient) => patient.id === patientId);
  const doctor = selectedPatient?.doctor || "";
  const initialComplaint = initialPrescription?.complaint || "";
  const [complaint, setComplaint] = useState(
    COMPLAINT_OPTIONS.includes(initialComplaint)
      ? initialComplaint
      : initialComplaint
        ? "Other"
        : "",
  );
  const [customComplaint, setCustomComplaint] = useState(
    COMPLAINT_OPTIONS.includes(initialComplaint) ? "" : initialComplaint,
  );
  const [chiefComplaints, setChiefComplaints] = useState(
    initialPrescription?.chiefComplaints || "",
  );
  const [history, setHistory] = useState(initialPrescription?.history || "");
  const [systemicExamination, setSystemicExamination] = useState(
    initialPrescription?.systemicExamination || "",
  );
  const [diagnosis, setDiagnosis] = useState(
    initialPrescription?.diagnosis || "",
  );
  const [allergies, setAllergies] = useState(
    initialPrescription?.allergies || "",
  );
  const [nextVisit, setNextVisit] = useState(
    initialPrescription?.nextVisit || "",
  );
  const [notes, setNotes] = useState(initialPrescription?.notes || "");
  const [medicineSearch, setMedicineSearch] = useState("");
  const [labSearch, setLabSearch] = useState("");
  const [medicineLines, setMedicineLines] = useState(
    initialPrescription?.medicines || [],
  );
  const [labTests, setLabTests] = useState(initialPrescription?.labTests || []);

  function toggleMedicine(medicine, checked) {
    setMedicineLines((items) =>
      checked
        ? [
            ...items,
            {
              medicineId: medicine.id,
              name: medicine.name,
              qty: 1,
              dosage: "",
              frequency: "",
              duration: "",
            },
          ]
        : items.filter((item) => item.medicineId !== medicine.id),
    );
  }

  function updateMedicine(medicineId, field, value) {
    setMedicineLines((items) =>
      items.map((item) =>
        item.medicineId === medicineId ? { ...item, [field]: value } : item,
      ),
    );
  }

  function toggleLabTest(test, checked) {
    setLabTests((items) =>
      checked
        ? [
            ...items,
            {
              testId: test.id,
              name: test.name,
              category: test.category,
              price: test.price,
              instructions: "",
            },
          ]
        : items.filter(
            (item) => item.testId !== test.id && item.name !== test.name,
          ),
    );
  }

  function submit(event) {
    event.preventDefault();
    if (
      !patientId ||
      !doctor.trim() ||
      (complaint === "Other" && !customComplaint.trim()) ||
      (medicineLines.length === 0 && labTests.length === 0)
    )
      return;
    onSave({
      ...(initialPrescription ? { id: initialPrescription.id } : {}),
      patientId,
      doctor: doctor.trim(),
      complaint: complaint === "Other" ? customComplaint.trim() : complaint,
      chiefComplaints: chiefComplaints.trim(),
      history: history.trim(),
      systemicExamination: systemicExamination.trim(),
      diagnosis: diagnosis.trim(),
      allergies,
      nextVisit,
      medicines: medicineLines,
      labTests,
      notes: notes.trim(),
    });
  }

  const visibleMedicines = medicines.filter((medicine) =>
    `${medicine.name} ${medicine.group || ""} ${medicine.drugCode || ""}`
      .toLowerCase()
      .includes(medicineSearch.toLowerCase()),
  );
  const visibleLabTests = pathologyTests.filter((test) =>
    `${test.name} ${test.category}`
      .toLowerCase()
      .includes(labSearch.toLowerCase()),
  );

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <form
        className="modal prescription-form redesigned-prescription"
        onClick={(event) => event.stopPropagation()}
        onSubmit={submit}
      >
        <div className="form-header">
          <span className="eyebrow">Doctor workspace</span>
          <h3>{initialPrescription ? "Edit OPD prescription" : "New OPD prescription"}</h3>
          <p>Start with investigations, then add medicines and instructions.</p>
        </div>
        <section className="prescription-section">
          <div className="prescription-section-title">
            <span>1</span>
            <div>
              <strong>Patient and clinical details</strong>
              <small>Review the visit before prescribing.</small>
            </div>
          </div>
          <label>
            Patient
            <select
              value={patientId}
              onChange={(event) => setPatientId(event.target.value)}
            >
              {patients.map((patient) => (
                <option key={patient.id} value={patient.id}>
                  {patient.name} - {patient.phone}
                </option>
              ))}
            </select>
          </label>
          <div className="form-row">
            <label>
              Registered doctor
              <input value={doctor} readOnly />
            </label>
            <label>
              Registered address
              <textarea value={selectedPatient?.address || ""} readOnly />
            </label>
            <label>
              chief complaint
              <select
                value={complaint}
                onChange={(event) => setComplaint(event.target.value)}
              >
                <option value="">Select complaint</option>
                {COMPLAINT_OPTIONS.map((option) => (
                  <option key={option}>{option}</option>
                ))}
              </select>
            </label>
          </div>
          {complaint === "Other" && (
            <label>
              Write complaint
              <input
                value={customComplaint}
                onChange={(event) => setCustomComplaint(event.target.value)}
                placeholder="Enter the patient's complaint"
                required
              />
            </label>
          )}
          <div className="form-row">
            <label>
              Allergies
              <input
                value={allergies}
                onChange={(event) => setAllergies(event.target.value)}
                placeholder="No known allergies / list allergies"
              />
            </label>
          </div>
          <div className="clinical-notes-grid">
            <label>
              History
              <textarea value={history} onChange={(event) => setHistory(event.target.value)} placeholder="Relevant medical, medication, or present history" />
            </label>
            <label>
              Systemic examination
              <textarea value={systemicExamination} onChange={(event) => setSystemicExamination(event.target.value)} placeholder="General and system examination findings" />
            </label>
            <label>
              Diagnosis
              <textarea value={diagnosis} onChange={(event) => setDiagnosis(event.target.value)} placeholder="Clinical diagnosis or provisional diagnosis" />
            </label>
          </div>
        </section>
        <section className="prescription-section">
          <div className="prescription-section-title">
            <span>2</span>
            <div>
              <strong>Pathology / lab tests</strong>
              <small>
                Select from the hospital catalog. Tests appear first on the
                bill.
              </small>
            </div>
          </div>
          <input
            className="search"
            value={labSearch}
            onChange={(event) => setLabSearch(event.target.value)}
            placeholder="Search pathology test"
          />
          <div className="lab-test-list">
            {visibleLabTests.map((test) => {
              const selected = labTests.some(
                (item) => item.testId === test.id || item.name === test.name,
              );
              return (
                <div className="lab-test-option" key={test.id}>
                  <label>
                    <input
                      type="checkbox"
                      checked={selected}
                      onChange={(event) =>
                        toggleLabTest(test, event.target.checked)
                      }
                    />
                    <span>
                      {test.name}
                      <small>
                        {test.category} · {currency(test.price)}
                      </small>
                    </span>
                  </label>
                  {selected && (
                    <input
                      value={
                        labTests.find(
                          (item) =>
                            item.testId === test.id || item.name === test.name,
                        )
                          ?.instructions || ""
                      }
                      onChange={(event) =>
                        setLabTests((items) =>
                          items.map((item) =>
                            item.testId === test.id || item.name === test.name
                              ? { ...item, instructions: event.target.value }
                              : item,
                          ),
                        )
                      }
                      placeholder="Instructions (optional)"
                    />
                  )}
                </div>
              );
            })}
          </div>
          {labTests.length > 0 && (
            <div className="selected-test-summary">
              {labTests.length} test{labTests.length === 1 ? "" : "s"} selected
            </div>
          )}
        </section>
        <section className="prescription-section">
          <div className="prescription-section-title">
            <span>3</span>
            <div>
              <strong>Medicines</strong>
              <small>Select medicines from store inventory.</small>
            </div>
          </div>
          <input
            className="search"
            value={medicineSearch}
            onChange={(event) => setMedicineSearch(event.target.value)}
            placeholder="Search medicine, group, or drug code"
          />
          <div className="medicine-picker">
            {visibleMedicines.map((medicine) => {
              const selected = medicineLines.some(
                (item) => item.medicineId === medicine.id,
              );
              const expired = daysUntil(medicine.expiry) < 0;
              const line = medicineLines.find(
                (item) => item.medicineId === medicine.id,
              );
              return (
                <div
                  className={
                    expired ? "medicine-option disabled" : "medicine-option"
                  }
                  key={medicine.id}
                >
                  <label>
                    <input
                      type="checkbox"
                      checked={selected}
                      disabled={expired}
                      onChange={(event) =>
                        toggleMedicine(medicine, event.target.checked)
                      }
                    />
                    <span>
                      {medicine.name}
                      <small>
                        {medicine.qty} available · {currency(medicine.price)}
                      </small>
                    </span>
                  </label>
                  {selected && (
                    <div className="prescription-line">
                      <input
                        type="number"
                        min="1"
                        max={medicine.qty}
                        value={line.qty}
                        onChange={(event) =>
                          updateMedicine(
                            medicine.id,
                            "qty",
                            Math.min(
                              medicine.qty,
                              Math.max(
                                1,
                                parseInt(event.target.value, 10) || 1,
                              ),
                            ),
                          )
                        }
                        placeholder="Quantity"
                        aria-label={`Quantity for ${medicine.name}`}
                      />
                      <input
                        value={line.route}
                        onChange={(event) =>
                          updateMedicine(
                            medicine.id,
                            "route",
                            event.target.value,
                          )
                        }
                        placeholder="route"
                      />
                      <input
                        value={line.frequency}
                        onChange={(event) =>
                          updateMedicine(
                            medicine.id,
                            "frequency",
                            event.target.value,
                          )
                        }
                        placeholder="Frequency"
                      />
                      <input
                        value={line.duration}
                        onChange={(event) =>
                          updateMedicine(
                            medicine.id,
                            "duration",
                            event.target.value,
                          )
                        }
                        placeholder="Duration"
                      />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </section>
        <label>
          Doctor notes
          <textarea
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            placeholder="Instructions for patient or pharmacy"
          />
        </label>
        <div className="modal-actions">
          <button type="button" className="btn" onClick={onCancel}>
            Cancel
          </button>
          <button type="submit" className="btn primary">
            Send prescription
          </button>
        </div>
      </form>
    </div>
  );
}

function PrescriptionForm({
  patients,
  medicines,
  pathologyTests,
  initialPatientId,
  onCancel,
  onSave,
}) {
  const [patientId, setPatientId] = useState(
    initialPatientId ||
      patients.find((patient) => patient.status === "Waiting for doctor")?.id ||
      patients[0]?.id ||
      "",
  );
  const [doctor, setDoctor] = useState("");
  const [medicineLines, setMedicineLines] = useState([]);
  const [labTests, setLabTests] = useState([]);
  const [labTestSearch, setLabTestSearch] = useState("");
  const [complaint, setComplaint] = useState("");
  const [allergies, setAllergies] = useState("");
  const [notes, setNotes] = useState("");
  const [medicineSearch, setMedicineSearch] = useState("");

  function submit(event) {
    event.preventDefault();
    if (
      !patientId ||
      !doctor.trim() ||
      (medicineLines.length === 0 && labTests.length === 0)
    )
      return;
    onSave({
      patientId,
      doctor: doctor.trim(),
      medicines: medicineLines,
      labTests,
      complaint,
      allergies,
      notes: notes.trim(),
    });
  }

  function toggleMedicine(medicine, checked) {
    setMedicineLines((items) =>
      checked
        ? [
            ...items,
            {
              medicineId: medicine.id,
              name: medicine.name,
              qty: 1,
              dosage: "",
              frequency: "",
              duration: "",
            },
          ]
        : items.filter((item) => item.medicineId !== medicine.id),
    );
  }

  function updateLine(medicineId, field, value) {
    setMedicineLines((items) =>
      items.map((item) =>
        item.medicineId === medicineId ? { ...item, [field]: value } : item,
      ),
    );
  }

  function toggleLabTest(test, checked) {
    setLabTests((items) =>
      checked
        ? [
            ...items,
            {
              testId: test.id,
              name: test.name,
              category: test.category,
              price: test.price,
              instructions: "",
            },
          ]
        : items.filter((item) => item.testId !== test.id),
    );
  }

  function updateLabTest(testId, instructions) {
    setLabTests((items) =>
      items.map((item) =>
        item.testId === testId ? { ...item, instructions } : item,
      ),
    );
  }

  const visibleMedicines = medicines.filter((medicine) =>
    `${medicine.name} ${medicine.group || ""} ${medicine.drugCode || ""}`
      .toLowerCase()
      .includes(medicineSearch.toLowerCase()),
  );
  const visibleLabTests = pathologyTests.filter((test) =>
    `${test.name} ${test.category}`
      .toLowerCase()
      .includes(labTestSearch.toLowerCase()),
  );

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <form
        className="modal prescription-form"
        onClick={(event) => event.stopPropagation()}
        onSubmit={submit}
      >
        <h3>New OPD prescription</h3>
        <label>
          Patient
          <select
            value={patientId}
            onChange={(event) => setPatientId(event.target.value)}
          >
            {patients.map((patient) => (
              <option key={patient.id} value={patient.id}>
                {patient.name} - {patient.phone}
              </option>
            ))}
          </select>
        </label>
        <label>
          Doctor name
          <input
            value={doctor}
            onChange={(event) => setDoctor(event.target.value)}
            placeholder="Dr. name"
            required
          />
        </label>
        <div className="medicine-picker">
          <strong>Select medicines from store inventory</strong>
          <input
            className="search medicine-search"
            value={medicineSearch}
            onChange={(event) => setMedicineSearch(event.target.value)}
            placeholder="Search medicine, group, or drug code"
          />
          {visibleMedicines.map((medicine) => {
            const selected = medicineLines.some(
              (item) => item.medicineId === medicine.id,
            );
            const expired = daysUntil(medicine.expiry) < 0;
            return (
              <div
                className={
                  expired ? "medicine-option disabled" : "medicine-option"
                }
                key={medicine.id}
              >
                <label>
                  <input
                    type="checkbox"
                    checked={selected}
                    disabled={expired}
                    onChange={(event) =>
                      toggleMedicine(medicine, event.target.checked)
                    }
                  />
                  {medicine.name}
                  <small>
                    {medicine.qty} available - {currency(medicine.price)}
                  </small>
                </label>
                {selected && (
                  <div className="prescription-line">
                    <input
                      type="number"
                      min="1"
                      max={medicine.qty}
                      value={
                        medicineLines.find(
                          (item) => item.medicineId === medicine.id,
                        )?.qty || 1
                      }
                      onChange={(event) =>
                        updateLine(
                          medicine.id,
                          "qty",
                          Math.min(
                            medicine.qty,
                            Math.max(1, parseInt(event.target.value, 10) || 1),
                          ),
                        )
                      }
                      placeholder="Qty"
                    />
                    <input
                      value={
                        medicineLines.find(
                          (item) => item.medicineId === medicine.id,
                        )?.dosage || ""
                      }
                      onChange={(event) =>
                        updateLine(medicine.id, "dosage", event.target.value)
                      }
                      placeholder="Dosage"
                    />
                    <input
                      value={
                        medicineLines.find(
                          (item) => item.medicineId === medicine.id,
                        )?.frequency || ""
                      }
                      onChange={(event) =>
                        updateLine(medicine.id, "frequency", event.target.value)
                      }
                      placeholder="Frequency"
                    />
                    <input
                      value={
                        medicineLines.find(
                          (item) => item.medicineId === medicine.id,
                        )?.duration || ""
                      }
                      onChange={(event) =>
                        updateLine(medicine.id, "duration", event.target.value)
                      }
                      placeholder="Duration"
                    />
                  </div>
                )}
              </div>
            );
          })}
          {visibleMedicines.length === 0 && (
            <div className="empty">No medicines match this search.</div>
          )}
        </div>
        <label>
          Doctor notes
          <input
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            placeholder="Instructions for patient or pharmacy"
          />
        </label>
        <div className="modal-actions">
          <button type="button" className="btn" onClick={onCancel}>
            Cancel
          </button>
          <button type="submit" className="btn primary">
            Send to medical store
          </button>
        </div>
      </form>
    </div>
  );
}

function MedicineForm({ initial, onCancel, onSave }) {
  const [name, setName] = useState(initial?.name || "");
  const [batch, setBatch] = useState(initial?.batch || "");
  const [expiry, setExpiry] = useState(initial?.expiry || "");
  const [qty, setQty] = useState(initial?.qty ?? "");
  const [price, setPrice] = useState(initial?.price ?? "");
  const [gst, setGst] = useState(initial?.gst ?? 12);

  function submit(e) {
    e.preventDefault();
    if (!name.trim() || !batch.trim() || !expiry || qty === "" || price === "")
      return;
    onSave({
      name: name.trim(),
      batch: batch.trim(),
      expiry,
      qty: parseInt(qty, 10),
      price: parseFloat(price),
      gst: parseInt(gst, 10),
    });
  }

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <form
        className="modal"
        onClick={(e) => e.stopPropagation()}
        onSubmit={submit}
      >
        <h3>{initial ? "Edit medicine" : "Add medicine"}</h3>
        <label>
          Name
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Paracetamol 500mg"
            required
          />
        </label>
        <div className="form-row">
          <label>
            Batch number
            <input
              value={batch}
              onChange={(e) => setBatch(e.target.value)}
              placeholder="PC22B"
              required
            />
          </label>
          <label>
            Expiry date
            <input
              type="date"
              value={expiry}
              onChange={(e) => setExpiry(e.target.value)}
              required
            />
          </label>
        </div>
        <div className="form-row">
          <label>
            Quantity
            <input
              type="number"
              min="0"
              value={qty}
              onChange={(e) => setQty(e.target.value)}
              required
            />
          </label>
          <label>
            Price per unit
            <input
              type="number"
              min="0"
              step="0.01"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              required
            />
          </label>
          <label>
            GST rate
            <select value={gst} onChange={(e) => setGst(e.target.value)}>
              {GST_OPTIONS.map((g) => (
                <option key={g} value={g}>
                  {g}%
                </option>
              ))}
            </select>
          </label>
        </div>
        <div className="modal-actions">
          <button type="button" className="btn" onClick={onCancel}>
            Cancel
          </button>
          <button type="submit" className="btn primary">
            {initial ? "Save changes" : "Add to inventory"}
          </button>
        </div>
      </form>
    </div>
  );
}

