.history-row { display: grid; grid-template-columns: 1.2fr 1.5fr 0.7fr auto; align-items: center; gap: 18px; border-bottom: 1px solid #edf2ed; padding: 15px 0; }
.history-row > div { display: flex; flex-direction: column; gap: 4px; }
.history-row > strong { color: #1f6b58; text-align: right; }
.records-layout { padding: 30px 36px 40px; max-width: 1100px; margin: 0 auto; }
.records-toolbar { display: flex; justify-content: flex-end; margin-bottom: 14px; }
.records-toolbar .search { min-width: 300px; }
.patient-records { display: grid; gap: 10px; }
.patient-record { background: #fff; border: 1px solid #dfe7df; border-radius: 12px; overflow: hidden; }
.patient-record.selected { border-color: #9fc8ae; }
.patient-record-main { display: grid; grid-template-columns: 36px 1fr auto; align-items: center; gap: 12px; width: 100%; border: 0; background: transparent; color: #203b33; cursor: pointer; font-family: inherit; padding: 15px 17px; text-align: left; }
.patient-avatar { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: #e2f2e8; color: #1f6b58; font-weight: 700; }
.patient-record-main span:nth-child(2), .history-item span:first-child, .prescription-row > div { display: flex; flex-direction: column; gap: 4px; }
.patient-record-main small, .history-item small, .prescription-row small { color: #789087; font-size: 11px; }
.patient-chevron { color: #1f6b58; font-size: 20px; }
.patient-history { border-top: 1px solid #edf2ed; padding: 14px 18px 16px 65px; }
.patient-history p { color: #71807a; font-size: 12px; margin: 7px 0 12px; }
.patient-summary { display: flex; flex-wrap: wrap; gap: 18px; margin-bottom: 10px; }
.patient-summary span:not(.status), .patient-summary strong { display: flex; flex-direction: column; gap: 3px; }
.patient-summary small { color: #789087; font-size: 11px; }
.record-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.queue-filter { display: flex; align-items: end; justify-content: space-between; gap: 14px; margin-bottom: 14px; padding: 12px 14px; background: #f8fbf8; border: 1px solid #dfe7df; border-radius: 10px; color: #789087; font-size: 12px; }
.queue-filter label { display: flex; flex-direction: column; gap: 5px; color: #55605a; font-size: 11px; }
.queue-filter select { border: 1px solid #d3dfd5; border-radius: 7px; background: #fff; color: #203b33; font: 12px 'Inter', sans-serif; padding: 7px 10px; }
.queue-view-toggle { display: flex; gap: 4px; padding: 3px; background: #edf3ed; border-radius: 8px; }
.queue-view-toggle button { border: 0; border-radius: 6px; background: transparent; color: #587067; cursor: pointer; font: 600 11px 'Inter', sans-serif; padding: 7px 10px; }
.queue-view-toggle button.active { background: #1f6b58; color: #fff; }
.history-item, .prescription-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 12px; border-top: 1px solid #edf2ed; padding: 11px 0; }
.status { border-radius: 20px; font-size: 10px; font-weight: 700; padding: 4px 9px; white-space: nowrap; }
.status.ok { background: #e2f2e8; color: #1f6b58; }
.status.warn { background: #fff0cf; color: #9c6a16; }
.prescription-queue { padding: 5px 20px; }
.prescription-row { grid-template-columns: 1fr auto auto; }
.medicine-picker { max-height: 270px; overflow: auto; border: 1px solid #dfe7df; border-radius: 8px; padding: 10px; }
.medicine-picker > strong { display: block; color: #203b33; font-size: 12px; margin-bottom: 8px; }
.medicine-option { border-top: 1px solid #edf2ed; padding: 8px 0; }
.medicine-option > label { display: flex; flex-direction: row; align-items: center; gap: 7px; color: #203b33; font-size: 12px; }
.medicine-option > label small { color: #789087; margin-left: auto; font-size: 10px; }
.medicine-option.disabled { opacity: .45; }
.prescription-line { display: grid; grid-template-columns: 54px 1fr 1fr 1fr; gap: 5px; padding: 7px 0 0 22px; }
  .prescription-line input { min-width: 0; border: 1px solid #d3dfd5; border-radius: 5px; padding: 6px; font: 11px 'Inter', sans-serif; }
  .medicine-search { width: 100%; min-width: 0; margin-bottom: 6px; }
  .print-prescription { display: none; }
  .prescription-letterhead { display: flex; align-items: center; gap: 14px; border-bottom: 2px solid #1f6b58; padding-bottom: 12px; }
  .prescription-letterhead img { width: 250px; max-height: 84px; object-fit: contain; }
  .prescription-letterhead strong { display: block; color: #173c32; font-size: 20px; }
  .prescription-letterhead span { display: block; color: #71807a; font-size: 11px; margin-top: 3px; }
  .prescription-print-title { color: #173c32; font: 700 14px Georgia, serif; margin-top: 18px; }
  .prescription-print-subtitle { color: #173c32; font-weight: 700; margin-top: 22px; }
  .prescription-notes { border-top: 1px solid #ddd; margin-top: 22px; padding-top: 12px; }
  .prescription-notes p { margin: 6px 0 0; }
  .prescription-signature { margin-top: 48px; text-align: right; }

.inventory-layout { padding: 24px 28px; }
.stock-table { width: 100%; border-collapse: collapse; background: #FBFCF9; border: 1px solid #DEE3D7; border-radius: 10px; overflow: hidden; }
.stock-table th {
  text-align: left; font-size: 11px; font-weight: 500; color: #7A857A;
  padding: 10px 14px; border-bottom: 1px solid #DEE3D7;
}
.stock-table td { padding: 10px 14px; font-size: 13px; border-bottom: 1px solid #EEF1EA; }
.row-actions { display: flex; gap: 12px; }

.modal-backdrop {
  position: fixed; inset: 0; background: rgba(35, 40, 35, 0.4);
  display: flex; align-items: center; justify-content: center; padding: 20px; z-index: 50;
}
.modal {
  background: #FBFCF9; border-radius: 10px; padding: 22px; width: 100%; max-width: 440px;
  display: flex; flex-direction: column; gap: 12px;
}
.modal h3 { font-family: 'Zilla Slab', serif; margin: 0 0 4px 0; font-size: 16px; }
.modal label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; color: #55605A; flex: 1; }
.modal input, .modal select {
  border: 1px solid #C9D1C1; border-radius: 7px; padding: 8px 10px; font-size: 13px; font-family: inherit;
}
.form-row { display: flex; gap: 10px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 6px; }
.form-header { border-bottom: 1px solid #e5ece6; padding-bottom: 12px; }
.form-header h3 { margin-bottom: 4px; }
.form-header p, .prescription-section-title small { color: #789087; font-size: 11px; margin: 0; }
.prescription-form { max-width: 700px; max-height: calc(100vh - 28px); overflow-y: auto; }
.prescription-section { border: 1px solid #e0ebe2; border-radius: 10px; padding: 13px; background: #fcfefc; }
.prescription-section-title { display: flex; align-items: flex-start; gap: 9px; margin-bottom: 12px; }
.prescription-section-title > span { display: grid; place-items: center; width: 23px; height: 23px; border-radius: 50%; background: #dff1e5; color: #1f6b58; font-size: 11px; font-weight: 700; flex: 0 0 auto; }
.prescription-section-title strong { display: block; color: #203b33; font-size: 13px; margin-bottom: 2px; }
.lab-test-list { max-height: 220px; overflow-y: auto; margin-top: 8px; border-top: 1px solid #edf2ed; }
.lab-test-option { border-bottom: 1px solid #edf2ed; padding: 8px 0; }
.lab-test-option label { display: flex; flex-direction: row; align-items: center; gap: 8px; }
.lab-test-option label span { display: flex; flex-direction: column; gap: 2px; color: #203b33; font-size: 12px; }
.lab-test-option small, .medicine-option label small { display: block; color: #789087; font-size: 10px; }
.lab-test-option > input { width: calc(100% - 26px); margin: 6px 0 0 26px; }
.pathology-queue { overflow-x: auto; }
.pathology-table { min-width: 900px; }
.selected-test-summary { color: #1f6b58; font-size: 11px; font-weight: 600; margin-top: 8px; }
.bill-tests { border: 1px solid #d6e9dc; border-radius: 8px; background: #f5fbf6; margin-bottom: 14px; padding: 10px; }
.clinical-notes-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px; }
.clinical-notes-grid textarea { min-height: 68px; }
  .clinical-print-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 24px; border-bottom: 1px solid #999; padding: 14px 0; }
  .clinical-print-grid div { display: flex; flex-direction: column; gap: 3px; }
  .clinical-print-grid strong { font-size: 10px; text-transform: uppercase; color: #555; }
.bill-section-title { color: #1f6b58; font-size: 12px; font-weight: 700; margin-bottom: 6px; }
.bill-test-row { display: flex; justify-content: space-between; border-top: 1px solid #e2efe5; padding: 7px 0; color: #203b33; font-size: 12px; }

.app {
  --ink: #182b27;
  --muted: #71807a;
  --line: #dfe7df;
  --paper: #ffffff;
  background: #f4f7f2;
  color: var(--ink);
}
.topbar { background: #ffffff; border-bottom-color: var(--line); padding: 16px 36px; }
.brand-mark { background: #1f6b58; color: #f4f7f2; border-radius: 11px; font-size: 23px; font-weight: 700; }
.hospital-logo { width: 116px; height: 44px; object-fit: contain; }
.brand-name { color: #173c32; font-size: 19px; letter-spacing: -0.2px; }
.brand-sub { color: var(--muted); }
.brand-contact { color: #1f6b58; font-size: 10px; font-weight: 600; margin-top: 3px; }
.tabs { background: #edf3ed; border-radius: 10px; }
.tab { color: #587067; padding: 8px 18px; }
.tab.active { background: #1f6b58; box-shadow: 0 3px 8px rgba(31, 107, 88, 0.18); }
.overview-strip { display: grid; grid-template-columns: minmax(260px, 1.5fr) repeat(3, minmax(145px, 0.55fr)); gap: 14px; padding: 28px 36px 8px; align-items: stretch; }
.welcome-block { padding: 6px 4px; }
.eyebrow { display: block; color: #789087; font-size: 10px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; margin-bottom: 6px; }
.welcome-block h1 { margin: 0; color: #173c32; font-family: 'Zilla Slab', serif; font-size: 27px; line-height: 1.1; }
.welcome-block p { color: var(--muted); font-size: 12px; margin: 8px 0 0; }
.metric-card { display: flex; gap: 11px; align-items: center; background: var(--paper); border: 1px solid var(--line); border-radius: 12px; padding: 14px; min-height: 72px; box-shadow: 0 4px 14px rgba(34, 58, 47, 0.035); }
.metric-card strong, .metric-card span { display: block; }
.metric-card strong { color: #173c32; font-size: 22px; line-height: 1; }
.metric-card div span { color: var(--muted); font-size: 11px; margin-top: 5px; }
.metric-icon { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 9px; font-weight: 700; font-size: 16px; }
.metric-icon.green { color: #1f6b58; background: #e2f2e8; }
.metric-icon.amber { color: #9c6a16; background: #fff0cf; }
.metric-icon.rose { color: #aa5946; background: #fbe4df; }
.billing-layout { gap: 16px; padding: 20px 36px 36px; }
.panel { border-color: var(--line); border-radius: 12px; box-shadow: 0 7px 20px rgba(34, 58, 47, 0.035); padding: 20px; }
.panel-head { margin-bottom: 16px; }
.panel-head .eyebrow { margin-bottom: 4px; }
.panel-head h2 { color: #173c32; font-size: 19px; }
.search, .patient-grid input { border-color: #d3dfd5; background: #fbfdfb; }
.search:focus, .patient-grid input:focus { outline-color: #2d8069; }
.med-row { border-color: #e5ece6; background: #fcfefc; padding: 11px 12px; transition: border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease; }
.med-row:hover { border-color: #b6d4c2; transform: translateY(-1px); box-shadow: 0 4px 10px rgba(31, 107, 88, 0.07); }
.med-name, .cart-name { color: #203b33; font-weight: 600; }
.btn { border-color: #2b755f; color: #21624f; }
.btn.primary, .tab.active { background: #1f6b58; border-color: #1f6b58; }
.btn.primary:hover { background: #185845; }
.patient-form { border-bottom-color: var(--line); }
.inventory-layout { padding: 28px 36px 36px; }
.inventory-layout .panel-head { align-items: end; }
.inventory-summary { color: var(--muted); font-size: 12px; }
.inventory-summary strong { color: #1f6b58; font-size: 16px; margin-left: 5px; }
.stock-table { border-color: var(--line); box-shadow: 0 7px 20px rgba(34, 58, 47, 0.035); }
.stock-table th { background: #f8fbf8; color: #789087; }
.stock-table td { border-bottom-color: #edf2ed; }
.section-actions { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.danger-button { border-color: #b65442; color: #a13c24; }
.visit-history { border-top: 1px solid #edf2ed; margin-top: 12px; padding-top: 10px; }
.visit-history > strong { color: #203b33; display: block; font-size: 12px; margin-bottom: 7px; }
.visit-history-row { display: grid; grid-template-columns: 92px 1fr 150px; gap: 10px; border-top: 1px solid #f0f3ef; color: #55605a; font-size: 11px; padding: 7px 0; }
.import-button { position: relative; overflow: hidden; }
.import-button input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.medicine-directory .section-heading .search { min-width: 320px; }
.doctor-med-list { max-height: 660px; }
.form-hint { color: #789087; font-size: 11px; margin: -6px 0 0; }
.patient-registration-form { max-width: 620px; max-height: calc(100vh - 40px); overflow-y: auto; }
.modal textarea { border: 1px solid #C9D1C1; border-radius: 7px; padding: 8px 10px; font-size: 13px; font-family: inherit; min-height: 62px; resize: vertical; }
.modal input:focus, .modal select:focus, .modal textarea:focus { outline: 2px solid #2d8069; outline-offset: 1px; }

@media (max-width: 820px) {
  .topbar { padding: 14px 20px; }
  .overview-strip { grid-template-columns: 1fr 1fr 1fr; padding: 24px 20px 4px; }
  .welcome-block { grid-column: 1 / -1; }
  .billing-layout { padding: 18px 20px 28px; }
  .inventory-layout { padding: 24px 20px; overflow-x: auto; }
  .dashboard-layout, .invoices-layout { padding: 24px 20px; }
  .dashboard-metrics { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 520px) {
  .topbar { padding: 14px 16px; flex-wrap: wrap; gap: 12px; }
  .save-indicator { display: none; }
  .account-controls { margin-left: auto; }
  .billing-layout, .inventory-layout { padding: 16px; }
  .overview-strip { grid-template-columns: 1fr; padding: 20px 16px 2px; gap: 8px; }
  .welcome-block { grid-column: auto; padding-bottom: 8px; }
  .welcome-block h1 { font-size: 24px; }
  .metric-card { min-height: 62px; }
  .billing-layout { gap: 14px; }
  .panel { padding: 14px; }
  .panel-head { align-items: stretch; flex-direction: column; }
  .search { min-width: 0; width: 100%; }
  .patient-grid { grid-template-columns: 1fr; }
  .med-row { flex-wrap: wrap; }
  .med-main { flex-basis: calc(100% - 12px); }
  .badge { margin-left: 0; }
  .cart-row { grid-template-columns: 1fr 52px 74px; }
  .cart-row .link-btn { grid-column: 1 / -1; justify-self: start; }
  .tabs { order: 3; width: 100%; overflow-x: auto; }
  .tab { flex: 1 0 auto; padding-left: 12px; padding-right: 12px; }
  .dashboard-layout, .invoices-layout { padding: 20px 16px 28px; }
  .records-layout { padding: 20px 16px 28px; }
  .records-toolbar .search { min-width: 0; width: 100%; }
  .dashboard-intro, .section-heading { align-items: flex-start; flex-direction: column; }
  .section-actions { justify-content: flex-start; width: 100%; }
  .section-actions .btn { flex: 1; }
  .dashboard-intro h1, .section-heading h1 { font-size: 25px; }
  .dashboard-intro .btn, .section-heading .btn { width: 100%; }
  .dashboard-metrics, .dashboard-columns { grid-template-columns: 1fr; }
  .medicine-directory .section-heading .search { min-width: 0; }
  .hospital-logo { width: 96px; height: 38px; }
  .brand-sub { max-width: 210px; line-height: 1.25; }
  .quick-actions { grid-template-columns: 1fr; }
  .quick-action { flex-direction: row; align-items: center; }
  .quick-action strong { margin: 0 0 0 4px; }
  .history-row { grid-template-columns: 1fr auto; gap: 9px 12px; }
  .history-row > div:nth-child(2) { grid-column: 1; }
  .history-row > strong { grid-column: 2; grid-row: 1 / span 2; }
  .history-row .btn { grid-column: 1 / -1; width: 100%; }
  .patient-history { padding-left: 18px; }
  .patient-summary { gap: 10px 16px; }
  .visit-history-row { grid-template-columns: 1fr; gap: 3px; }
  .queue-filter { align-items: stretch; flex-direction: column; }
  .queue-filter select { width: 100%; }
  .queue-view-toggle { width: 100%; }
  .queue-view-toggle button { flex: 1; }
  .prescription-line { grid-template-columns: 1fr 1fr; padding-left: 0; }
  .prescription-form { max-height: calc(100vh - 16px); padding: 16px; }
  .prescription-section { padding: 11px; }
  .prescription-row { grid-template-columns: 1fr auto; }
  .prescription-row .btn { grid-column: 1 / -1; width: 100%; }
}

@media print {
  @page { margin: 16mm; }
  body { background: white; }
  .app > *:not(.print-bill):not(.print-prescription) { display: none !important; }
  .print-bill, .print-prescription {
    display: block;
    color: #111;
    font-family: Arial, sans-serif;
    font-size: 12px;
    text-align: left;
  }
  .print-brand { font-family: Georgia, serif; font-size: 22px; font-weight: 700; }
  .print-title { font-size: 14px; margin-top: 4px; text-transform: uppercase; letter-spacing: 1px; }
  .print-meta { display: flex; justify-content: space-between; border-bottom: 1px solid #999; margin-top: 18px; padding-bottom: 8px; }
  .print-patient-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 24px; border-bottom: 1px solid #999; padding: 14px 0; }
  .print-patient-grid div { display: flex; flex-direction: column; gap: 3px; }
  .print-patient-grid strong { font-size: 10px; text-transform: uppercase; color: #555; }
  .print-table { width: 100%; border-collapse: collapse; margin-top: 18px; }
  .print-table th, .print-table td { border-bottom: 1px solid #ddd; padding: 8px 4px; text-align: left; }
  .print-table th:nth-child(2), .print-table td:nth-child(2), .print-table th:last-child, .print-table td:last-child { text-align: right; }
  .print-total { display: flex; justify-content: space-between; margin-top: 7px; }
  .print-total.grand { border-top: 1px solid #111; font-weight: 700; font-size: 14px; margin-top: 12px; padding-top: 9px; }
  .print-footer { border-top: 1px solid #ddd; color: #555; margin-top: 30px; padding-top: 10px; text-align: center; }
  .prescription-print-table th, .prescription-print-table td { vertical-align: top; }
  .prescription-print-table th:not(:first-child), .prescription-print-table td:not(:first-child) { text-align: left; }
}
`;
